from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter()

PAGE = r"""
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>AutoFlow — возврат клиентов</title><style>
:root{font-family:Inter,Segoe UI,Arial,sans-serif;color:#eaf0f7;background:#0b1220}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,#1d3551 0,transparent 36%),#0b1220;min-height:100vh}
header{display:flex;justify-content:space-between;align-items:center;padding:20px max(5vw,20px);border-bottom:1px solid #26364a;background:#0c1626cc;position:sticky;top:0;backdrop-filter:blur(12px);z-index:2}
.brand{font-size:23px;font-weight:800;letter-spacing:-1px}.brand span{color:#73d6a1}.muted{color:#91a2b7}.wrap{max-width:1180px;margin:34px auto;padding:0 20px}.hero{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:26px}h1{font-size:34px;margin:0 0 8px}h2{font-size:19px;margin:0 0 18px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.panel,.stat{background:#121f30;border:1px solid #293b50;border-radius:16px;padding:20px}.stat strong{display:block;font-size:30px;margin-top:9px}.layout{display:grid;grid-template-columns:1.3fr .7fr;gap:16px;margin-top:16px}.btn{background:#76d7a2;color:#082014;border:0;padding:11px 16px;border-radius:10px;font-weight:750;cursor:pointer}.btn.secondary{background:#26384c;color:#eaf0f7}.btn.danger{background:#57313a;color:#fff}.row{display:flex;gap:9px;align-items:center;flex-wrap:wrap}input,select,textarea{width:100%;background:#0b1625;color:#eaf0f7;border:1px solid #35485e;border-radius:9px;padding:11px;margin:6px 0 12px;font:inherit}label{font-size:13px;color:#aab9c9}form{margin-top:14px}.formgrid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}.item{padding:13px 0;border-bottom:1px solid #293b50}.item:last-child{border:0}.tag{font-size:12px;background:#314b45;color:#a6efc2;padding:5px 8px;border-radius:20px}.hidden{display:none!important}.auth{max-width:460px;margin:8vh auto;padding:28px}.auth h1{font-size:30px}.tabs{display:flex;gap:8px;margin-bottom:14px}.tabs button{flex:1}.draft{font-size:13px;color:#c5d1dd;background:#0b1625;padding:10px;border-radius:8px;margin-top:8px}.empty{color:#91a2b7;padding:18px 0}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.layout{grid-template-columns:1fr}.hero{align-items:start;flex-direction:column}}@media(max-width:480px){.grid,.formgrid{grid-template-columns:1fr}h1{font-size:27px}}
.topnav{display:flex;gap:8px;max-width:1180px;margin:18px auto 0;padding:0 20px;flex-wrap:wrap}.topnav a{color:#b9c8d8;text-decoration:none;padding:9px 13px;border:1px solid #293b50;border-radius:9px;font-size:13px}.topnav a:hover{color:#8be0ad;border-color:#76d7a2}.panel h2{letter-spacing:-.35px}.stat{position:relative;overflow:hidden}.stat:after{content:"";position:absolute;width:72px;height:72px;border-radius:50%;background:#76d7a210;right:-18px;top:-22px}.search{max-width:280px}.subform{border-top:1px solid #293b50;margin-top:18px;padding-top:16px}.clientcar{font-size:12px;color:#9eb3c8;margin-top:5px}.item b{font-size:14px}.item .muted{font-size:12px;margin-top:4px}.btn:focus,input:focus,select:focus{outline:2px solid #76d7a2;outline-offset:2px}@media(max-width:650px){header{padding:15px 18px}.topnav{overflow:auto;flex-wrap:nowrap}.topnav a{white-space:nowrap}.wrap{margin-top:22px}}\n</style></head><body><header><div class="brand">Auto<span>Flow</span></div><div class="row"><span id="org" class="muted"></span><button id="logout" class="btn secondary hidden" onclick="logout()">Выйти</button></div></header>
<section id="auth" class="panel auth"><div class="brand">Auto<span>Flow</span></div><p class="muted">Возвращайте клиентов. Увеличивайте повторные визиты.</p><div class="tabs"><button class="btn" onclick="mode='login';authForm()">Войти</button><button class="btn secondary" onclick="mode='register';authForm()">Регистрация</button></div><form id="authform"><div id="orgfield"><label>Название автосервиса</label><input name="organization_name" placeholder="Например, АвтоПрофи"></div><label>Email</label><input name="email" type="email" required placeholder="you@example.com"><label>Пароль (минимум 10 символов)</label><input name="password" type="password" minlength="10" required><button class="btn" style="width:100%">Продолжить</button></form><p id="authmsg" class="muted"></p></section>
<nav id="appnav" class="topnav hidden"><a href="#overview">Обзор</a><a href="#clients-panel">Клиенты</a><a href="#vehicle-panel">Автомобили</a><a href="#return-panel">Возврат клиентов</a><a href="#deferred-panel">Отложенные работы</a><a href="#visits-panel">История визитов</a></nav><main id="app" class="wrap hidden"><div id="overview" class="hero"><div><div class="tag">ПАНЕЛЬ УПРАВЛЕНИЯ</div><h1>Возвращайте клиентов, а не теряйте их</h1><div class="muted">Контролируйте визиты и вовремя связывайтесь с клиентами.</div></div><button class="btn" onclick="loadAll()">Обновить данные ↻</button></div>
<div class="grid"><div class="stat"><span class="muted">Клиенты</span><strong id="sclients">0</strong></div><div class="stat"><span class="muted">Визиты</span><strong id="svisits">0</strong></div><div class="stat"><span class="muted">Пора вернуть</span><strong id="sdue">0</strong></div><div class="stat"><span class="muted">Выручка визитов</span><strong id="srevenue">0 ₽</strong></div><div class="stat"><span class="muted">Отложенные работы</span><strong id="sdeferred">0</strong></div><div class="stat"><span class="muted">Потенциал возврата</span><strong id="sdeferredvalue">0 ₽</strong></div></div>
<div class="layout"><section id="clients-panel" class="panel"><div class="row" style="justify-content:space-between"><h2>Клиентская база</h2><input id="clientsearch" class="search" placeholder="Поиск по имени или телефону"></div><form id="clientform"><div class="formgrid"><div><label>Имя клиента *</label><input name="full_name" required placeholder="Иван Иванов"></div><div><label>Телефон</label><input name="phone" placeholder="+7 900 000-00-00"></div><div><label>Email</label><input name="email" type="email"></div><div><label>Заметка</label><input name="notes" placeholder="Предпочтения, детали"></div></div><label style="display:flex;gap:9px;align-items:center;margin:4px 0 8px"><input name="marketing_consent" type="checkbox" style="width:auto;margin:0"> Есть подтверждённое согласие на рекламу</label><input name="consent_evidence" placeholder="Реквизит подтверждения согласия (если отмечено)"><button class="btn">+ Добавить клиента</button></form><div id="clients"><div class="empty">Пока нет клиентов. Добавьте первого.</div></div></section>
<section id="vehicle-panel" class="panel"><h2>Автомобили клиентов</h2><form id="carform"><label>Владелец</label><select name="client_id" id="carclient" required><option value="">Сначала добавьте клиента</option></select><div class="formgrid"><div><label>Марка</label><input name="make" required placeholder="Toyota"></div><div><label>Модель</label><input name="model" required placeholder="Camry"></div><div><label>Год</label><input name="year" type="number" min="1900" max="2100" placeholder="2020"></div><div><label>Госномер</label><input name="plate_number" placeholder="А123АА"></div></div><button class="btn">+ Добавить автомобиль</button></form><div class="muted">Автомобили отображаются в карточке клиента.</div></section><section class="panel"><h2>Добавить визит</h2><form id="visitform"><label>Клиент *</label><select name="client_id" id="visitclient" required><option value="">Сначала добавьте клиента</option></select><label>Выполненная работа *</label><input name="service_name" required placeholder="Замена масла"><label>Следующее обслуживание</label><input name="next_due_at" type="date"><label>Сумма, ₽</label><input name="amount_rub" type="number" min="0" placeholder="6500"><label>Комментарий</label><input name="notes" placeholder="5W-30, фильтр..."><button class="btn">Сохранить визит</button></form><p id="visitmsg" class="muted"></p></section></div>
<div class="layout"><section id="return-panel" class="panel"><h2>Smart Return — пора связаться</h2><p class="muted">Черновики сообщений для ручной отправки. AutoFlow ничего не отправляет автоматически.</p><div id="returns"><div class="empty">Нет клиентов, которым пора вернуться.</div></div></section><section id="visits-panel" class="panel"><h2>Последние визиты</h2><div id="visits"><div class="empty">История пока пуста.</div></div></section></div>
</main><script>
let mode='login',allClients=[];const $=s=>document.querySelector(s);function authForm(){$('#orgfield').classList.toggle('hidden',mode!=='register');$('#authform').querySelector('button').textContent=mode==='register'?'Создать аккаунт':'Войти';$('#authmsg').textContent=''}
async function api(url,opts={}){let r=await fetch(url,{...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}});let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'Ошибка запроса');return d}
$('#authform').onsubmit=async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));try{await api('/api/auth/'+mode,{method:'POST',body:JSON.stringify(f)});await boot()}catch(err){$('#authmsg').textContent=err.message}};
async function logout(){await api('/api/auth/logout',{method:'POST'});location.reload()}
$('#clientform').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let consent=d.marketing_consent==='on',evidence=d.consent_evidence;delete d.marketing_consent;delete d.consent_evidence;if(consent&&!evidence){alert('Укажите подтверждение согласия.');return}try{let created=await api('/api/clients',{method:'POST',body:JSON.stringify(d)});if(consent)await api('/api/clients/'+created.id+'/consents',{method:'POST',body:JSON.stringify({channel:'sms',purpose:'marketing',granted:true,evidence_reference:evidence})});e.target.reset();await loadAll()}catch(err){alert(err.message)}};
$('#deferredform').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.client_id=Number(d.client_id);d.estimated_amount_rub=d.estimated_amount_rub?Number(d.estimated_amount_rub):null;d.follow_up_at=d.follow_up_at?new Date(d.follow_up_at+'T12:00:00Z').toISOString():null;try{await api('/api/deferred-services',{method:'POST',body:JSON.stringify(d)});e.target.reset();await loadAll()}catch(err){alert(err.message)}};
async function setDeferredStatus(id,status){try{await api('/api/deferred-services/'+id,{method:'PATCH',body:JSON.stringify({status})});await loadAll()}catch(err){alert(err.message)}}
$('#carform').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.client_id=Number(d.client_id);d.year=d.year?Number(d.year):null;try{await api('/api/vehicles',{method:'POST',body:JSON.stringify(d)});e.target.reset();await loadAll()}catch(err){alert(err.message)}};
$('#clientsearch').oninput=renderClients;
$('#visitform').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.client_id=Number(d.client_id);d.amount_rub=d.amount_rub?Number(d.amount_rub):null;d.next_due_at=d.next_due_at?new Date(d.next_due_at+'T12:00:00Z').toISOString():null;try{await api('/api/visits',{method:'POST',body:JSON.stringify(d)});e.target.reset();$('#visitmsg').textContent='Визит сохранён';await loadAll()}catch(err){$('#visitmsg').textContent=err.message}};
async function loadAll(){let [dash,clients,visits,returns,deferred]=await Promise.all([api('/api/dashboard'),api('/api/clients'),api('/api/visits'),api('/api/smart-return'),api('/api/deferred-services')]);$('#sclients').textContent=dash.clients;$('#svisits').textContent=dash.visits;$('#sdue').textContent=dash.due;$('#srevenue').textContent=dash.revenue_rub.toLocaleString('ru-RU')+' ₽';$('#sdeferred').textContent=dash.deferred_count;$('#sdeferredvalue').textContent=dash.deferred_value_rub.toLocaleString('ru-RU')+' ₽';allClients=clients;let options=clients.length?clients.map(c=>'<option value="'+c.id+'">'+esc(c.full_name)+'</option>').join(''):'<option value="">Сначала добавьте клиента</option>';$('#visitclient').innerHTML=options;$('#carclient').innerHTML=options;$('#deferredclient').innerHTML=options;renderClients();$('#visits').innerHTML=visits.length?visits.slice(0,8).map(v=>'<div class="item"><b>'+esc(v.client)+'</b><div class="muted">'+esc(v.service_name)+' · '+new Date(v.visited_at).toLocaleDateString('ru-RU')+' · '+v.amount_rub+' ₽</div></div>').join(''):'<div class="empty">История пока пуста.</div>';$('#deferredlist').innerHTML=deferred.length?deferred.map(x=>'<div class="item"><b>'+esc(x.client)+'</b><div>'+esc(x.service_name)+' · '+esc(x.status)+' · '+x.estimated_amount_rub.toLocaleString('ru-RU')+' ₽</div><div class="row" style="margin-top:8px">'+(x.status==='recovered'||x.status==='lost'?'': '<button class="btn secondary" onclick="setDeferredStatus('+x.id+',\'contacted\')">Связались</button><button class="btn secondary" onclick="setDeferredStatus('+x.id+',\'recovered\')">Вернули работу</button><button class="btn danger" onclick="setDeferredStatus('+x.id+',\'lost\')">Закрыть без продажи</button>')+'</div></div>').join(''):'<div class="empty">Пока отложенных работ нет.</div>';$('#returns').innerHTML=returns.length?returns.map(x=>'<div class="item"><b>'+esc(x.client)+'</b> <span class="tag">'+esc(x.service)+'</span><div class="muted">'+esc(x.phone||'Телефон не указан')+' · срок '+new Date(x.due_at).toLocaleDateString('ru-RU')+'</div><div class="draft">'+(x.has_marketing_consent?esc(x.draft):'Нет подтверждённого согласия на маркетинговые сообщения — не отправляйте рекламу. Сначала уточните и зафиксируйте согласие.')+'</div>'+(x.has_marketing_consent?'<button class="btn secondary" style="margin-top:8px" onclick="copyText(this)">Скопировать текст</button>':'')+'</div>').join(''):'<div class="empty">Отлично! Пока никого не нужно возвращать.</div>'}
function statusLabel(s){return ({open:'Открыта',contacted:'Связались',booked:'Запланирован визит',recovered:'Работа возвращена',lost:'Закрыта без продажи'})[s]||s};function renderClients(){let q=($('#clientsearch')?.value||'').toLowerCase();let filtered=allClients.filter(c=>(c.full_name+' '+(c.phone||'')+' '+(c.email||'')).toLowerCase().includes(q));$('#clients').innerHTML=filtered.length?filtered.map(c=>'<div class="item"><b>'+esc(c.full_name)+'</b><div class="muted">'+esc(c.phone||c.email||'Контакты не указаны')+'</div>'+(c.vehicles?.length?c.vehicles.map(v=>'<div class="clientcar">🚘 '+esc(v.make+' '+v.model+(v.year?' · '+v.year:''))+'</div>').join(''):'')+'</div>').join(''):'<div class="empty">Ничего не найдено.</div>'}
function copyText(btn){navigator.clipboard.writeText(btn.previousElementSibling.textContent).then(()=>btn.textContent='Скопировано ✓')}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function boot(){try{let me=await api('/api/auth/me');$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');$('#logout').classList.remove('hidden');$('#appnav').classList.remove('hidden');$('#org').textContent=me.organization;await loadAll()}catch(e){$('#auth').classList.remove('hidden');$('#app').classList.add('hidden');$('#logout').classList.add('hidden');$('#appnav').classList.add('hidden')}}
authForm();boot();
</script></body></html>
"""

@router.get("/", response_class=HTMLResponse, include_in_schema=False)
def home():
    return PAGE
